def actualizar_datos_demo(apps, schema_editor):
    """Solo cambia filas que conservan el texto original de la demostración."""
    alias = schema_editor.connection.alias
    Merchant = apps.get_model('beneficios', 'Merchant')
    Movement = apps.get_model('beneficios', 'Movement')
    User = apps.get_model('identidad', 'User')

    renamed = {}
    for old_code, (old_name, code, name, address, description) in MERCHANTS.items():
        merchant = Merchant.objects.using(alias).filter(code=old_code, name=old_name).first()
        if merchant and not Merchant.objects.using(alias).filter(code=code).exists():
            merchant.code, merchant.name, merchant.address, merchant.description = code, name, address, description
            merchant.save(update_fields=['code', 'name', 'address', 'description'])
            renamed[old_name] = name

    # Las descripciones están cifradas: se comparan después de leerlas.
    for movement in Movement.objects.using(alias).only('pk', 'description').iterator():
        description = MOVEMENTS.get(movement.description)
        if description is None and movement.description.startswith(PAYMENT_PREFIX):
            merchant = movement.description.removeprefix(PAYMENT_PREFIX)
            description = f'Compra en {renamed.get(merchant, merchant)}'[:120]
        if description:
            movement.description = description
            movement.save(update_fields=['description'])

    for user in User.objects.using(alias).filter(username__in=SURNAMES):
        if user.last_name == 'Prueba':
            user.last_name = SURNAMES[user.username]
            user.save(update_fields=['last_name'])


